class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) {
            return null;
        }

        // get all nodes
        var allNodes = bfs(node);

        // clone nodes
        var nodesMap = new HashMap<Node, Node>();
        for (var point : allNodes) {
            nodesMap.put(point, new Node(point.val));
        }

        // set neighbors
        for (var point : allNodes) {
            var newNode = nodesMap.get(point);
            for (var neighbor : point.neighbors) {
                newNode.neighbors.add(nodesMap.get(neighbor));
            }
        }

        return nodesMap.get(node);
    }

    List<Node> bfs(Node node) {
        var queue = new LinkedList<Node>();
        var visit = new HashSet<Node>();
        var result = new ArrayList<Node>();

        queue.offer(node);
        visit.add(node);

        while (!queue.isEmpty()) {
            var size = queue.size();
            for (var i = 0; i < size; i++) {
                var cur = queue.poll();
                result.add(cur);

                for (var neighbor : cur.neighbors) {
                    if (visit.contains(neighbor)) {
                        continue;
                    }

                    queue.offer(neighbor);
                    visit.add(neighbor);
                }
            }
        }

        return result;
    }
}

